//! Edge-case integration tests for scale-stat — generated by bug-hunter agent.
//!
//! ferrum-core is a `cdylib`-only crate; internal scale/transform math lives in
//! `pub(crate)` modules inaccessible from integration tests. These tests exercise
//! the public `ferrum_scene` types that the scale/stat pipeline produces as output,
//! validating structural contracts that would break if scale bugs (NaN leaks,
//! degenerate domains, null handling) propagated into the scene graph.

#[cfg(test)]
mod tests {
    use ferrum_scene::{
        BlendMode, Color, CoordKind, FillStroke, MarkBatch, MarkBatchKind, Panel,
        PathCmd, Rect, SceneGraph, SceneNode, Tick, TickLevel,
    };

    fn default_fill_stroke() -> FillStroke {
        FillStroke {
            fill: Some(Color::rgb(70, 130, 180)),
            stroke: None,
            stroke_width: 0.0,
            opacity: 1.0,
            stroke_dash: None,
            stroke_opacity: 1.0,
            fill_opacity: 1.0,
            angle: 0.0,
        }
    }

    fn make_panel(marks: Vec<MarkBatch>) -> Panel {
        Panel {
            id: 0,
            plot_area: Rect { x: 50.0, y: 10.0, w: 500.0, h: 350.0 },
            clip: Rect { x: 50.0, y: 10.0, w: 500.0, h: 350.0 },
            coord: CoordKind::Cartesian {
                x_domain: Some((0.0, 10.0)),
                y_domain: Some((0.0, 10.0)),
                expand: true,
                clip: true,
            },
            grid: vec![],
            marks,
            axes: vec![],
            annotations: vec![],
            strip_title: vec![],
        }
    }

    // ── NaN leak detection in scene node coordinates ───────────────────────

    /// Circle nodes with NaN cx/cy would produce invalid SVG. Verify that
    /// finite coordinates round-trip; NaN coordinates serialize as `null`
    /// (not a number literal) in JSON.
    #[test]
    fn circle_nan_coordinates_serialize_as_null_not_literal() {
        let node = SceneNode::Circle {
            cx: f64::NAN,
            cy: f64::NAN,
            r: 3.0,
            style: default_fill_stroke(),
        };
        let json = serde_json::to_string(&node).expect("NaN circle serializes");
        // serde_json serializes NaN as `null` by default when using
        // serialize_f64 (the default). Verify it does NOT produce "NaN".
        assert!(
            !json.contains("NaN"),
            "JSON must not contain literal 'NaN': {json}"
        );
        assert!(json.contains("null"), "NaN f64 should serialize as null: {json}");
    }

    /// Path with NaN in MoveTo/LineTo is what would happen if a degenerate
    /// domain (min==max) caused 0/0 in the linear scale. Verify it serializes.
    #[test]
    fn path_nan_coordinates_serialize_without_panic() {
        let node = SceneNode::Path {
            commands: vec![
                PathCmd::MoveTo { x: f64::NAN, y: 0.0 },
                PathCmd::LineTo { x: 100.0, y: f64::NAN },
                PathCmd::Close,
            ],
            style: default_fill_stroke(),
            closed: true,
        };
        let json = serde_json::to_string(&node).expect("NaN path serializes");
        assert!(!json.contains("NaN"), "JSON must not contain literal 'NaN'");
    }

    /// Rect with zero width or height (degenerate bar from collapsed domain).
    #[test]
    fn rect_zero_dimension_serializes_and_deserializes() {
        let node = SceneNode::Rect {
            x: 50.0,
            y: 100.0,
            w: 0.0,
            h: 200.0,
            style: default_fill_stroke(),
            corner_radius: 0.0,
        };
        let json = serde_json::to_string(&node).expect("zero-width rect serializes");
        let back: SceneNode = serde_json::from_str(&json).expect("deserializes");
        match back {
            SceneNode::Rect { w, h, .. } => {
                assert_eq!(w, 0.0, "zero width must survive");
                assert_eq!(h, 200.0);
            }
            other => panic!("expected Rect, got {other:?}"),
        }
    }

    /// Rect with NaN dimensions (what would happen if scale output is NaN).
    #[test]
    fn rect_nan_dimensions_serialize_as_null() {
        let node = SceneNode::Rect {
            x: f64::NAN,
            y: f64::NAN,
            w: f64::NAN,
            h: f64::NAN,
            style: default_fill_stroke(),
            corner_radius: 0.0,
        };
        let json = serde_json::to_string(&node).expect("NaN rect serializes");
        assert!(!json.contains("NaN"));
    }

    // ── Degenerate domain round-trips in CoordKind ────────────────────────

    /// CoordKind with degenerate domain [5.0, 5.0] (single-value data).
    #[test]
    fn cartesian_degenerate_domain_round_trips() {
        let coord = CoordKind::Cartesian {
            x_domain: Some((5.0, 5.0)),
            y_domain: Some((0.0, 0.0)),
            expand: true,
            clip: true,
        };
        let json = serde_json::to_string(&coord).expect("serialize");
        let back: CoordKind = serde_json::from_str(&json).expect("deserialize");
        match back {
            CoordKind::Cartesian { x_domain, y_domain, .. } => {
                let (x_lo, x_hi) = x_domain.unwrap();
                assert_eq!(x_lo, 5.0);
                assert_eq!(x_hi, 5.0);
                let (y_lo, y_hi) = y_domain.unwrap();
                assert_eq!(y_lo, 0.0);
                assert_eq!(y_hi, 0.0);
            }
            other => panic!("expected Cartesian, got {other:?}"),
        }
    }

    /// CoordKind with very large domain values (1e300).
    #[test]
    fn cartesian_extreme_domain_values_round_trip() {
        let coord = CoordKind::Cartesian {
            x_domain: Some((-1e300, 1e300)),
            y_domain: Some((1e-300, 1e300)),
            expand: false,
            clip: false,
        };
        let json = serde_json::to_string(&coord).expect("serialize extreme");
        let back: CoordKind = serde_json::from_str(&json).expect("deserialize extreme");
        match back {
            CoordKind::Cartesian { x_domain, y_domain, .. } => {
                let (x_lo, x_hi) = x_domain.unwrap();
                assert!((x_lo - (-1e300)).abs() < 1e290);
                assert!((x_hi - 1e300).abs() < 1e290);
                let (y_lo, _) = y_domain.unwrap();
                assert!(y_lo > 0.0 && y_lo < 1e-299);
            }
            other => panic!("expected Cartesian, got {other:?}"),
        }
    }

    // ── Tick generation edge cases ────────────────────────────────────────

    /// A Tick with NaN pixel value would break SVG axis rendering.
    #[test]
    fn tick_nan_pixel_serializes_as_null() {
        let tick = Tick {
            value: 5.0,
            label: "5".to_string(),
            pixel: f64::NAN,
        };
        let json = serde_json::to_string(&tick).expect("serialize tick with NaN pixel");
        assert!(!json.contains("NaN"), "Tick pixel must not serialize as 'NaN': {json}");
    }

    /// Tick with infinity in value (edge case from log scale on zero input).
    #[test]
    fn tick_infinity_serializes_as_null() {
        let tick = Tick {
            value: f64::INFINITY,
            label: "Inf".to_string(),
            pixel: 500.0,
        };
        let json = serde_json::to_string(&tick).expect("serialize tick with Inf");
        assert!(!json.contains("Infinity"), "JSON must not contain 'Infinity': {json}");
    }

    /// TickLevel with empty ticks vec (what happens when domain is degenerate).
    #[test]
    fn tick_level_empty_ticks_round_trips() {
        let level = TickLevel {
            min_zoom: 1.0,
            max_zoom: 100.0,
            ticks: vec![],
        };
        let json = serde_json::to_string(&level).expect("serialize empty TickLevel");
        let back: TickLevel = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(back.ticks.len(), 0);
    }

    /// TickLevel with max_zoom = INFINITY should survive JSON round-trip.
    /// The zoom system uses INFINITY as "no upper limit" sentinel but
    /// serde_json serializes it as null, breaking deserialization.
    #[test]
    fn tick_level_infinity_max_zoom_round_trips() { // BUG: f64::INFINITY in TickLevel.max_zoom serializes as null, fails deserialization
        let level = TickLevel {
            min_zoom: 1.0,
            max_zoom: f64::INFINITY,
            ticks: vec![],
        };
        let json = serde_json::to_string(&level).expect("serialize with Infinity");
        let back: TickLevel = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(back.ticks.len(), 0);
        assert!(back.max_zoom.is_infinite());
    }

    // ── Empty / zero-mark scene graphs ────────────────────────────────────

    /// A scene with a panel but zero marks (all data filtered by null).
    #[test]
    fn panel_zero_marks_round_trips() {
        let panel = make_panel(vec![]);
        let json = serde_json::to_string(&panel).expect("serialize empty panel");
        let back: Panel = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(back.marks.len(), 0);
    }

    /// MarkBatch with zero nodes (group had all-null values, nothing to render).
    #[test]
    fn mark_batch_empty_nodes_round_trips() {
        let batch = MarkBatch {
            kind: MarkBatchKind::Point,
            nodes: vec![],
            data_indices: Some(vec![]),
            tooltips: None,
            hrefs: None,
            descriptions: None,
            keys: None,
            blend: BlendMode::Normal,
            stroke_cap: None,
            stroke_join: None,
            packed_instances: None,
        };
        let json = serde_json::to_string(&batch).expect("serialize empty batch");
        let back: MarkBatch = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(back.nodes.len(), 0);
    }

    /// SceneGraph with zero panels (empty dataset).
    #[test]
    fn scene_graph_zero_panels_round_trips() {
        let scene = SceneGraph {
            width: 600.0,
            height: 400.0,
            background: Some(Color::rgb(255, 255, 255)),
            title: vec![],
            legend: vec![],
            panels: vec![],
            decorations: vec![],
            selections: vec![],
            interaction: Default::default(),
            chart_description: None,
        };
        let json = serde_json::to_string(&scene).expect("serialize");
        let back: SceneGraph = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(back.panels.len(), 0);
    }

    // ── Numeric precision at scale boundaries ─────────────────────────────

    /// Verify that very precise coordinates survive JSON round-trip.
    #[test]
    fn circle_precise_coordinates_survive_round_trip() {
        let node = SceneNode::Circle {
            cx: 0.123456789012345,
            cy: 999.987654321098,
            r: 0.001,
            style: default_fill_stroke(),
        };
        let json = serde_json::to_string(&node).expect("serialize");
        let back: SceneNode = serde_json::from_str(&json).expect("deserialize");
        match back {
            SceneNode::Circle { cx, cy, r, .. } => {
                assert!(
                    (cx - 0.123456789012345).abs() < 1e-12,
                    "cx precision lost: {cx}"
                );
                assert!(
                    (cy - 999.987654321098).abs() < 1e-9,
                    "cy precision lost: {cy}"
                );
                assert!((r - 0.001).abs() < 1e-15, "r precision lost: {r}");
            }
            other => panic!("expected Circle, got {other:?}"),
        }
    }

    /// Path with subnormal coordinates (very small values near scale boundaries).
    #[test]
    fn path_subnormal_coordinates_round_trip() {
        let node = SceneNode::Path {
            commands: vec![
                PathCmd::MoveTo { x: 1e-308, y: 1e-308 },
                PathCmd::LineTo { x: 5e-308, y: 5e-308 },
                PathCmd::Close,
            ],
            style: default_fill_stroke(),
            closed: true,
        };
        let json = serde_json::to_string(&node).expect("serialize subnormal path");
        let back: SceneNode = serde_json::from_str(&json).expect("deserialize");
        match &back {
            SceneNode::Path { commands, .. } => {
                match &commands[0] {
                    PathCmd::MoveTo { x, y } => {
                        assert!(*x > 0.0 && *x < 1e-307, "subnormal x lost: {x}");
                        assert!(*y > 0.0 && *y < 1e-307, "subnormal y lost: {y}");
                    }
                    other => panic!("expected MoveTo, got {other:?}"),
                }
            }
            other => panic!("expected Path, got {other:?}"),
        }
    }
}
